        host.innerHTML = '<div class="fx-st" data-k="' + k + '"><p class="fx-n">' + (STEPS.indexOf(k) + 1) + ' / 4</p><h2>' + T[0] + '</h2><div class="fx-ch">' +
          T[1].map(function (o, i) { return '<button type="button" data-v="' + esc(o.key) + '" style="--i:' + i + '">' + esc(o.label) + '</button>'; }).join('') +
          (k === 'style' ? '<button type="button" class="skip" data-v="any">לא משנה לי</button>' : '') + '</div></div>';
        var f = host.querySelector('button'); f && f.focus({ preventScroll: true });
